	QNTSTONE SMALLINT,
	DSTSTONE SMALLINT,
	PRIMARY KEY (SSN),
    FOREIGN KEY (SSN) REFERENCES tmp_df8.ssn_master(SSN) ON DELETE CASCADE
);

COMMIT;



